// ============================================================
//  GIG RADAR – SETTINGS
//  Edit the values below, then save. Everything else reads from here.
// ============================================================
return [{
  json: {
    // 1) Where to look. Any RSS/Atom feed works – add or remove freely.
    feeds: [
      {
        name: 'Reddit',
        url: 'https://www.reddit.com/r/forhire+DoneDirtCheap+slavelabour+n8n+automation+nocode+zapier/new/.rss?limit=100',
      },
      {
        name: 'n8n Community',
        url: 'https://community.n8n.io/c/jobs/13.rss',
      },
    ],

    // Sources that are job boards: every post is a job/offer, so no "hiring" words are required.
    jobBoards: ['forhire', 'donedirtcheap', 'slavelabour', 'community.n8n.io'],

    // Sources that are already about automation, so the topic keywords are not required.
    automationCommunities: ['n8n', 'automation', 'nocode', 'zapier', 'community.n8n.io'],

    // 2) Words that mean "this post is about automation work".
    topicKeywords: [
      'n8n', 'make.com', 'integromat', 'zapier', 'automation', 'automate', 'workflow',
      'ai agent', 'ai assistant', 'chatbot', 'gpt', 'openai', 'llm', 'deepseek', 'claude',
      'api', 'integration', 'webhook', 'scrap', 'airtable', 'notion', 'google sheets',
      'crm', 'gohighlevel', 'telegram bot', 'whatsapp', 'python script',
    ],

    // 3) Who you are – the AI scores every gig against this.
    myProfile:
      'I build AI automations with n8n, LLM APIs (DeepSeek/OpenAI), webhooks, REST APIs, ' +
      'Google Sheets, Notion, Telegram and email. I prefer small, well-defined remote tasks ' +
      '(a few hours to a few days, roughly under $500 fixed price) that I can later turn into ' +
      'portfolio pieces. Any language is fine. Not interested in full-time jobs, unpaid work, ' +
      'or "equity only" offers.',

    // 4) AI settings
    model: 'deepseek-flash',          // cheap + fast. 'deepseek-v4-pro' for harder judgement
    summaryLanguage: 'Simplified Chinese',
    minScore: 7,                      // only gigs scoring >= this (0-10) are sent to you
    maxAiChecksPerRun: 15,            // cost guard: max posts sent to the AI per run
    maxAgeHours: 48,                  // ignore posts older than this

    // 5) Where to send the alerts (see README: "Get your Telegram chat ID")
    telegramChatId: 'YOUR_CHAT_ID',
  },
}];

// Turns raw RSS entries into clean "post" objects and drops the obvious non-matches
// for free, before anything is sent to the (paid) AI.
const cfg = $('Config').first().json;
const lower = (list) => (list || []).map((s) => String(s).toLowerCase());
const jobBoards = lower(cfg.jobBoards);
const automationCommunities = lower(cfg.automationCommunities);
// Keywords match at the start of a word: "api" matches "API"/"APIs" but not "capital".
const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const topicRe = new RegExp('(?:^|[^a-z0-9])(?:' + lower(cfg.topicKeywords).map(escapeRe).join('|') + ')', 'i');
const maxAgeMs = (cfg.maxAgeHours || 48) * 3600 * 1000;

const FOR_HIRE = /\[\s*for\s*hire\s*\]|\bfor\s*hire\b|\[\s*offer\s*\]|available for (hire|freelance|work|projects?)|\bhire me\b|\bopen to work\b|\bmy services\b/i;
const HIRING = /\[\s*(hiring|task|paid)\s*\]|\bhiring\b|\bwe'?re hiring\b|looking for (a |an |some )?(freelancer|developer|dev|expert|specialist|consultant|someone|person|help|builder|engineer)|need(ed)? (a |an |some )?(freelancer|developer|dev|expert|specialist|someone|help|builder|engineer)|\bwill pay\b|\bpaid (task|gig|project|work)\b|\bbudget\b|\$\s?\d+|\d+\s?(usd|eur|€|gbp|£)\b/i;

const stripHtml = (html) =>
  String(html || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();

const out = [];
for (const item of $input.all()) {
  const e = item.json || {};
  if (!e.title || !e.link) continue; // failed feed / empty entry

  const link = String(e.link);
  const sub = (link.match(/reddit\.com\/r\/([^/]+)/i) || [])[1];
  const host = (link.match(/^https?:\/\/([^/]+)/i) || [])[1] || '';
  const sourceKey = (sub || host).toLowerCase();
  const source = sub ? `Reddit r/${sub}` : host.replace(/^www\./, '');

  const title = String(e.title).trim();
  let text = e.contentSnippet ? String(e.contentSnippet) : stripHtml(e.content || e.description);
  text = text.replace(/submitted by\s+\/u\/\S+.*$/i, '').trim(); // Reddit footer

  const dateStr = e.isoDate || e.pubDate;
  const date = dateStr ? new Date(dateStr) : null;
  if (date && !isNaN(date) && Date.now() - date.getTime() > maxAgeMs) continue;

  const head = `${title}\n${text.slice(0, 600)}`;
  const isJobBoard = jobBoards.includes(sourceKey);
  const isAutomationCommunity = automationCommunities.includes(sourceKey);

  if (FOR_HIRE.test(title)) continue; // people offering services, not clients

  const hiring = HIRING.test(head) || (isJobBoard && !sub); // forum job boards: every topic is a job
  const onTopic = isAutomationCommunity || topicRe.test(head);
  if (!hiring || !onTopic) continue;

  out.push({
    json: {
      id: String(e.id || e.guid || link),
      source,
      title,
      text: text.slice(0, 3000),
      link,
      author: String(e.author || e.creator || '').replace(/^\/u\//, ''),
      postedAt: date && !isNaN(date) ? date.toISOString() : null,
    },
  });
}
return out;

// Remembers which posts were already checked, so you never get the same gig twice
// and never pay the AI twice for it.
// NOTE: n8n only saves this memory for automatic (production) runs. When you click
// "Test workflow" by hand, everything counts as new – that's expected.
const cfg = $('Config').first().json;
const memory = $getWorkflowStaticData('global');
memory.seen = memory.seen || {};

// Forget entries older than 30 days so the memory stays small.
const cutoff = Date.now() - 30 * 24 * 3600 * 1000;
for (const [key, ts] of Object.entries(memory.seen)) {
  if (ts < cutoff) delete memory.seen[key];
}

const fresh = [];
const seenThisRun = new Set();
for (const item of $input.all()) {
  const key = item.json.link;
  if (memory.seen[key] || seenThisRun.has(key)) continue;
  seenThisRun.add(key);
  fresh.push(item);
}

// Newest first, then apply the cost guard. Posts beyond the limit are NOT marked
// as seen, so the next run picks them up.
fresh.sort((a, b) => String(b.json.postedAt || '').localeCompare(String(a.json.postedAt || '')));
const batch = fresh.slice(0, cfg.maxAiChecksPerRun || 15);
for (const item of batch) memory.seen[item.json.link] = Date.now();

return batch.map((item) => ({ json: item.json }));

// Builds one DeepSeek chat request per post.
const cfg = $('Config').first().json;

const system = `You screen freelance job posts for one freelancer and answer in json only.

The freelancer's profile:
${cfg.myProfile}

For the post you receive, return exactly this json shape:
{
  "is_hiring": true,
  "is_automation": true,
  "fit_score": 8,
  "budget": "$150 fixed",
  "effort": "a few hours",
  "difficulty": "easy",
  "summary": "one sentence: what the client wants built",
  "why": "one short sentence: why it does or does not fit the profile",
  "red_flags": ""
}

Rules:
- is_hiring: true only if the author wants to PAY someone for work. False if they offer their own services, ask a free question, or share a project.
- is_automation: true if the work is mainly automation, AI workflows, integrations, bots, scraping or scripting.
- budget: copy it from the post if stated (keep the currency), otherwise "unknown".
- effort: one of "a few hours", "1-3 days", "about a week", "ongoing / part-time", "full-time job", "unknown".
- difficulty: "easy", "medium" or "hard" for someone with the profile above.
- fit_score (0-10): 9-10 = small, clear, paid automation task that matches the profile; 7-8 = good match with minor gaps;
  4-6 = partial match (too big, vague, or skills missing); 0-3 = not hiring, not automation, unpaid, equity-only, or full-time job.
- red_flags: short note on scam signs (asks for upfront payment, personal data, off-platform crypto, "test task" that is real work), else "".
- Write "summary", "why" and "red_flags" in ${cfg.summaryLanguage}. Keep other values in English.`;

return $input.all().map((item) => {
  const p = item.json;
  const user = `Source: ${p.source}\nPosted: ${p.postedAt || 'unknown'}\nTitle: ${p.title}\n\n${p.text || '(no body text, judge from the title)'}`;
  return {
    json: {
      post: p,
      requestBody: {
        model: cfg.model || 'deepseek-flash',
        thinking: { type: 'disabled' },
        response_format: { type: 'json_object' },
        temperature: 0.2,
        max_tokens: 500,
        messages: [
          { role: 'system', content: system },
          { role: 'user', content: user },
        ],
      },
    },
  };
});

// Reads the AI verdicts, keeps the good gigs and formats a Telegram message for each.
const cfg = $('Config').first().json;
const memory = $getWorkflowStaticData('global');
memory.seen = memory.seen || {};
const minScore = Number(cfg.minScore ?? 7);

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const parseVerdict = (content) => {
  if (!content) return null;
  try { return JSON.parse(content); } catch (e) {}
  const m = String(content).match(/\{[\s\S]*\}/); // tolerate text around the json
  if (m) { try { return JSON.parse(m[0]); } catch (e) {} }
  return null;
};

const good = [];
let failed = 0;
$input.all().forEach((item, i) => {
  const post = $('Build AI request').itemMatching(i).json.post;
  const verdict = parseVerdict(item.json?.choices?.[0]?.message?.content);

  if (!verdict) {
    // AI call failed (no credit, timeout, empty answer...). Forget the post so the
    // next run tries it again instead of losing it.
    failed++;
    delete memory.seen[post.link];
    return;
  }

  const score = Number(verdict.fit_score) || 0;
  if (!verdict.is_hiring || !verdict.is_automation || score < minScore) return;

  const lines = [
    `🎯 <b>${score}/10</b> · ${esc(post.source)}`,
    `<b>${esc(post.title)}</b>`,
    '',
    `💬 ${esc(verdict.summary)}`,
    `💰 ${esc(verdict.budget || 'unknown')} · ⏱ ${esc(verdict.effort || 'unknown')} · 🧩 ${esc(verdict.difficulty || '?')}`,
    `👍 ${esc(verdict.why)}`,
  ];
  if (verdict.red_flags) lines.push(`⚠️ ${esc(verdict.red_flags)}`);
  lines.push('', `🔗 ${esc(post.link)}`);

  good.push({
    json: {
      chatId: cfg.telegramChatId,
      score,
      title: post.title,
      link: post.link,
      message: lines.join('\n').slice(0, 4000), // Telegram limit is 4096
    },
  });
});

if (failed) console.log(`${failed} AI call(s) failed – those posts will be retried next run.`);
return good.sort((a, b) => b.json.score - a.json.score);
